def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    color=next(v for row in grid for v in row if v not in (0,6))
    for r in range(h):
        cols=[c for c,v in enumerate(grid[r]) if v==color]
        for a,b in zip(cols,cols[1:]):
            if b>a+1 and all(grid[r][c]==6 for c in range(a+1,b)):
                for c in range(a+1,b): out[r][c]=2
    for c in range(w):
        rows=[r for r in range(h) if grid[r][c]==color]
        for a,b in zip(rows,rows[1:]):
            if b>a+1 and all(grid[r][c]==6 for r in range(a+1,b)):
                for r in range(a+1,b): out[r][c]=2
    return out

